// مولَّد تلقائياً من migrations/*.sql بواسطة scripts/gen-migrations.mjs. لا تعدّله يدوياً.
export const MIGRATIONS = [
  ["0001_init", "-- قاعدة بيانات المنصة العراقية (Cloudflare D1): حسابات Google وجلساتها وبيانات الطالب المتزامنة.\n-- لا نخزّن كلمات مرور: الدخول بحساب Google فقط. نخزّن الاسم والبريد فقط.\nCREATE TABLE IF NOT EXISTS users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  google_sub TEXT NOT NULL UNIQUE,\n  email TEXT NOT NULL,\n  name TEXT NOT NULL,\n  role TEXT NOT NULL DEFAULT 'student',\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at INTEGER NOT NULL\n);\nCREATE TABLE IF NOT EXISTS sessions (\n  token_hash TEXT PRIMARY KEY,\n  user_id INTEGER NOT NULL,\n  expires_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);\nCREATE TABLE IF NOT EXISTS user_data (\n  user_id INTEGER NOT NULL,\n  k TEXT NOT NULL,\n  v TEXT NOT NULL,\n  t INTEGER NOT NULL,\n  PRIMARY KEY (user_id, k)\n);\n"],
  ["0002_announcements", "-- التبليغات: يكتبها ممثل الدفعة أو المشرف، وتظهر لكل الطلاب في الرئيسية.\n-- الأدوار مخزنة في users.role كنص: student | uploader | rep | admin (لا تغيير في المخطط).\nCREATE TABLE IF NOT EXISTS announcements (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL DEFAULT '',\n  author_id INTEGER NOT NULL,\n  author_name TEXT NOT NULL,\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS announcements_time ON announcements (created_at DESC);\n"],
  ["0003_multi_university", "-- المنصة العراقية: هيكل متعدد الجامعات (Cloudflare D1 / SQLite)\n-- جامعة > كلية > قسم > مرحلة > كورس > مادة > محاضرة > ملف\n-- جدول users موجود في 0001 (google_sub, email, name, role, active)، فلا نعيد تعريفه.\n\nCREATE TABLE IF NOT EXISTS universities (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  slug TEXT NOT NULL UNIQUE,\n  name_ar TEXT NOT NULL,\n  name_en TEXT,\n  city TEXT,\n  is_active INTEGER NOT NULL DEFAULT 0   -- تُفتح فقط عند وجود ممثل وملفات\n);\nCREATE TABLE IF NOT EXISTS colleges (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  university_id INTEGER NOT NULL REFERENCES universities(id),\n  slug TEXT NOT NULL,\n  name_ar TEXT NOT NULL,\n  name_en TEXT,\n  is_active INTEGER NOT NULL DEFAULT 0,\n  UNIQUE (university_id, slug)\n);\nCREATE TABLE IF NOT EXISTS departments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  college_id INTEGER NOT NULL REFERENCES colleges(id),\n  name_ar TEXT NOT NULL,\n  name_en TEXT\n);\nCREATE TABLE IF NOT EXISTS stages (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  department_id INTEGER NOT NULL REFERENCES departments(id),\n  number INTEGER NOT NULL,\n  UNIQUE (department_id, number)\n);\nCREATE TABLE IF NOT EXISTS terms (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  stage_id INTEGER NOT NULL REFERENCES stages(id),\n  number INTEGER NOT NULL,\n  UNIQUE (stage_id, number)\n);\nCREATE TABLE IF NOT EXISTS subjects (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  term_id INTEGER NOT NULL REFERENCES terms(id),\n  code TEXT,\n  name_ar TEXT NOT NULL,\n  name_en TEXT,\n  professor TEXT,\n  credits REAL\n);\nCREATE TABLE IF NOT EXISTS lectures (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  subject_id INTEGER NOT NULL REFERENCES subjects(id),\n  number INTEGER NOT NULL,\n  title TEXT NOT NULL\n);\n-- kind: lecture ملزمة | exam سؤال وزاري | summary ملخص | other\n-- status: pending | approved | rejected | removed (لا يظهر إلا approved)\nCREATE TABLE IF NOT EXISTS files (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  lecture_id INTEGER REFERENCES lectures(id),\n  subject_id INTEGER NOT NULL REFERENCES subjects(id),\n  kind TEXT NOT NULL DEFAULT 'lecture',\n  label TEXT NOT NULL,\n  r2_key TEXT NOT NULL,\n  uploaded_by INTEGER REFERENCES users(id),\n  status TEXT NOT NULL DEFAULT 'pending',\n  reviewed_by INTEGER REFERENCES users(id),\n  created_at INTEGER NOT NULL\n);\n-- أدوار محصورة بكلية: ممثل كلية يرفع ويوافق على كليته فقط. college_id = 0 يعني كل المنصة.\nCREATE TABLE IF NOT EXISTS user_scopes (\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  role TEXT NOT NULL,                      -- uploader | rep | moderator\n  college_id INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (user_id, role, college_id)\n);\nCREATE TABLE IF NOT EXISTS user_profile (\n  user_id INTEGER PRIMARY KEY REFERENCES users(id),\n  college_id INTEGER REFERENCES colleges(id),\n  stage_id INTEGER REFERENCES stages(id)\n);\n-- \"أبلغ عن ملف\": حقوق نشر أو أخطاء\nCREATE TABLE IF NOT EXISTS reports (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  file_id INTEGER NOT NULL REFERENCES files(id),\n  reporter_id INTEGER REFERENCES users(id),\n  reason TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'open',\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_colleges_uni ON colleges(university_id);\nCREATE INDEX IF NOT EXISTS idx_subjects_term ON subjects(term_id);\nCREATE INDEX IF NOT EXISTS idx_files_subject_status ON files(subject_id, status);\nCREATE INDEX IF NOT EXISTS idx_files_pending ON files(status) WHERE status = 'pending';\n"],
  ["0004_scopes_rep_requests", "-- الفرق المستقلة وطلبات التمثيل (مطابقة لما ينشئه functions/_lib/scope.js عند التشغيل).\n-- scopes: من يملك صلاحية ممثل أو رافع على جامعة/كلية/قسم. المفتاح المركّب يمنع التكرار.\nCREATE TABLE IF NOT EXISTS scopes (\n  user_id INTEGER NOT NULL,\n  type TEXT NOT NULL,\n  node_id INTEGER NOT NULL,\n  level TEXT NOT NULL,\n  PRIMARY KEY (user_id, type, node_id)\n);\n-- rep_requests: طلبات الطلاب لتمثيل قسم/كلية/جامعة، يقرّرها المشرف (pending | approved | rejected).\nCREATE TABLE IF NOT EXISTS rep_requests (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  type TEXT NOT NULL,\n  node_id INTEGER NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  created_at TEXT NOT NULL\n);\n"],
  ["0005_rep_audit_indexes", "-- C1 (تطوير 02-A): إضافات تراكمية فقط، بلا حذف ولا تعديل لجداول موجودة.\n-- سجل تدقيق لمنح/سحب الصلاحيات وقرارات الطلبات.\nCREATE TABLE IF NOT EXISTS scope_audit (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  actor_id INTEGER NOT NULL,\n  target_user_id INTEGER NOT NULL,\n  action TEXT NOT NULL,            -- grant | revoke | approve | reject\n  type TEXT,\n  node_id INTEGER,\n  created_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_scope_audit_target ON scope_audit(target_user_id);\nCREATE INDEX IF NOT EXISTS idx_rep_requests_status ON rep_requests(status);\nCREATE INDEX IF NOT EXISTS idx_scopes_user ON scopes(user_id);\n"],
  ["0006_pdf_notes", "-- Step 63: كتابة الطالب وتظليله وبطاقاته على ملفات PDF تُحفظ في حسابه (بطلب محمد 2026-10-19). إضافة فقط: جدول جديد.\n-- صف لكل (طالب، ملف، جزء): الملف بمعرّف مختصر (بصمة مسار الملف، لا اسم ولا رابط)،\n-- والجزء ink:<رقم الصفحة> أو study أو layout أو occl. t وقت آخر تعديل بالمللي ثانية، ويُستعمل لكشف التعارض بين جهازين.\n-- لا يدخل هذا الجدول في تصدير المشرف؛ كل طالب يقرأ صفوفه فقط.\nCREATE TABLE IF NOT EXISTS pdf_notes (\n  user_id INTEGER NOT NULL,\n  doc TEXT NOT NULL,\n  k TEXT NOT NULL,\n  d TEXT NOT NULL,\n  t INTEGER NOT NULL,\n  PRIMARY KEY (user_id, doc, k)\n);\n"],
  ["0007_pdf_assets", "-- Step 66 (بطلب محمد 2026-10-22): الصور التي يُدرجها الطالب في PDF تُرفع إلى حسابه وتظهر على كل أجهزته.\n-- الصورة مقسّمة إلى أجزاء (d) لتبقى كل جملة صغيرة. المعرّف img_<32 حرفاً سداسياً> هو بصمة محتوى الصورة نفسها.\n-- إضافة فقط: جدول جديد. لا يدخل تصدير المشرف، وكل طالب يقرأ صوره فقط.\nCREATE TABLE IF NOT EXISTS pdf_assets (\n  user_id INTEGER NOT NULL,\n  id TEXT NOT NULL,\n  part INTEGER NOT NULL,\n  type TEXT NOT NULL,\n  d TEXT NOT NULL,\n  PRIMARY KEY (user_id, id, part)\n);\n"],
  ["0008_ai_study_assistant", "-- مساعد الدراسة الذكي والمرشد الأكاديمي (من حزمة الدمج، 2026-11). إضافة فقط: كل الجداول تبدأ بـ ai_ ولا يُعدَّل أي جدول قائم.\n-- department_key = d<رقم القسم>. user_id = رقم المستخدم في users (نصاً). نصوص الصفحات يرسلها متصفح الطالب من «اكتب وظلّل» وتبقى خاصة به.\n\nCREATE TABLE IF NOT EXISTS ai_department_knowledge (\n  id TEXT PRIMARY KEY,\n  department_key TEXT NOT NULL,\n  department_name TEXT NOT NULL,\n  category TEXT NOT NULL,\n  title TEXT NOT NULL,\n  content TEXT NOT NULL,\n  created_by TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_dept_kb_key ON ai_department_knowledge(department_key, category);\n\nCREATE TABLE IF NOT EXISTS ai_documents (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  course_id TEXT,\n  filename TEXT NOT NULL,\n  safe_name TEXT NOT NULL,\n  r2_object_key TEXT NOT NULL,\n  mime_type TEXT NOT NULL DEFAULT 'application/pdf',\n  size_bytes INTEGER NOT NULL,\n  sha256 TEXT NOT NULL,\n  page_count INTEGER NOT NULL DEFAULT 0,\n  text_page_count INTEGER NOT NULL DEFAULT 0,\n  ocr_needed_pages_json TEXT NOT NULL DEFAULT '[]',\n  status TEXT NOT NULL DEFAULT 'ready',\n  error_message TEXT,\n  created_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_documents_user ON ai_documents(user_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_ai_documents_sha256 ON ai_documents(user_id, sha256);\n\nCREATE TABLE IF NOT EXISTS ai_document_pages (\n  document_id TEXT NOT NULL,\n  page_number INTEGER NOT NULL,\n  text_content TEXT NOT NULL,\n  has_extractable_text INTEGER NOT NULL DEFAULT 1,\n  char_count INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (document_id, page_number),\n  FOREIGN KEY (document_id) REFERENCES ai_documents(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS ai_document_chunks (\n  chunk_id TEXT PRIMARY KEY,\n  document_id TEXT NOT NULL,\n  user_id TEXT NOT NULL,\n  page_number INTEGER NOT NULL,\n  chunk_index INTEGER NOT NULL,\n  content TEXT NOT NULL,\n  FOREIGN KEY (document_id) REFERENCES ai_documents(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_chunks_doc_page ON ai_document_chunks(document_id, page_number);\n\nCREATE TABLE IF NOT EXISTS ai_conversations (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  title TEXT NOT NULL,\n  document_id TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_conversations_user ON ai_conversations(user_id, updated_at DESC);\n\nCREATE TABLE IF NOT EXISTS ai_messages (\n  id TEXT PRIMARY KEY,\n  conversation_id TEXT NOT NULL,\n  user_id TEXT NOT NULL,\n  role TEXT NOT NULL,\n  task TEXT NOT NULL DEFAULT 'ask',\n  content TEXT NOT NULL,\n  citations_json TEXT NOT NULL DEFAULT '[]',\n  artifact_id TEXT,\n  provider_mode TEXT NOT NULL DEFAULT 'cloudflare',\n  status TEXT NOT NULL DEFAULT 'completed',\n  created_at TEXT NOT NULL,\n  FOREIGN KEY (conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_messages_conv ON ai_messages(conversation_id, created_at ASC);\n\nCREATE TABLE IF NOT EXISTS ai_artifacts (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  document_id TEXT,\n  conversation_id TEXT,\n  kind TEXT NOT NULL,\n  title TEXT NOT NULL,\n  page_refs_json TEXT NOT NULL DEFAULT '[]',\n  payload_json TEXT NOT NULL,\n  provider_mode TEXT NOT NULL DEFAULT 'cloudflare',\n  created_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_artifacts_user ON ai_artifacts(user_id, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS ai_quiz_attempts (\n  id TEXT PRIMARY KEY,\n  quiz_artifact_id TEXT NOT NULL,\n  user_id TEXT NOT NULL,\n  score INTEGER NOT NULL,\n  total INTEGER NOT NULL,\n  percentage INTEGER NOT NULL,\n  answers_json TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  FOREIGN KEY (quiz_artifact_id) REFERENCES ai_artifacts(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS ai_notebook_notes (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  document_id TEXT NOT NULL,\n  page_number INTEGER NOT NULL,\n  selected_text TEXT NOT NULL DEFAULT '',\n  action_type TEXT NOT NULL DEFAULT 'note',\n  note_content TEXT NOT NULL,\n  citations_json TEXT NOT NULL DEFAULT '[]',\n  artifact_id TEXT,\n  created_at TEXT NOT NULL,\n  FOREIGN KEY (document_id) REFERENCES ai_documents(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_notes_doc_page ON ai_notebook_notes(user_id, document_id, page_number);\n\nCREATE TABLE IF NOT EXISTS ai_quota_ledger (\n  reservation_id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  task TEXT NOT NULL,\n  units INTEGER NOT NULL DEFAULT 1,\n  status TEXT NOT NULL,\n  day_key TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_ai_quota_user_day ON ai_quota_ledger(user_id, day_key, status);\n\nCREATE TABLE IF NOT EXISTS ai_audit_logs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id TEXT,\n  action TEXT NOT NULL,\n  resource_type TEXT NOT NULL,\n  resource_id TEXT,\n  status_code INTEGER NOT NULL,\n  meta_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL\n);\n"],
  ["0009_university_onboarding", "-- University directory entries do not imply membership. Preserve all existing rows.\nCREATE TABLE IF NOT EXISTS university_onboarding (\n  university_id INTEGER PRIMARY KEY REFERENCES universities(id),\n  state TEXT NOT NULL CHECK (state IN ('registered', 'active', 'suspended')),\n  manager_id INTEGER NOT NULL REFERENCES users(id),\n  verified_at INTEGER,\n  updated_at INTEGER NOT NULL,\n  updated_by INTEGER NOT NULL REFERENCES users(id),\n  CHECK (state = 'registered' OR verified_at IS NOT NULL)\n);\n\nCREATE TABLE IF NOT EXISTS university_onboarding_audit (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  university_id INTEGER NOT NULL,\n  actor_id INTEGER NOT NULL,\n  manager_id INTEGER NOT NULL,\n  previous_state TEXT,\n  state TEXT NOT NULL,\n  verified_at INTEGER,\n  created_at INTEGER NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_university_onboarding_state ON university_onboarding(state);\nCREATE INDEX IF NOT EXISTS idx_university_onboarding_audit ON university_onboarding_audit(university_id, id DESC);\n\nCREATE TRIGGER IF NOT EXISTS university_onboarding_registered\nAFTER INSERT ON university_onboarding\nBEGIN\n  INSERT INTO university_onboarding_audit\n    (university_id, actor_id, manager_id, previous_state, state, verified_at, created_at)\n  VALUES\n    (NEW.university_id, NEW.updated_by, NEW.manager_id, NULL, NEW.state, NEW.verified_at, NEW.updated_at);\nEND;\n\nCREATE TRIGGER IF NOT EXISTS university_onboarding_changed\nAFTER UPDATE ON university_onboarding\nWHEN OLD.state <> NEW.state OR OLD.manager_id <> NEW.manager_id OR OLD.verified_at IS NOT NEW.verified_at\nBEGIN\n  INSERT INTO university_onboarding_audit\n    (university_id, actor_id, manager_id, previous_state, state, verified_at, created_at)\n  VALUES\n    (NEW.university_id, NEW.updated_by, NEW.manager_id, OLD.state, NEW.state, NEW.verified_at, NEW.updated_at);\nEND;\n"],
  ["0010_global_admins", "-- ADMIN_EMAILS remains the authority for owners. Delegated administrators are separate.\nCREATE TABLE IF NOT EXISTS global_admins (\n  user_id INTEGER PRIMARY KEY REFERENCES users(id),\n  active INTEGER NOT NULL CHECK (active IN (0,1)),\n  changed_by INTEGER NOT NULL REFERENCES users(id),\n  changed_at INTEGER NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS global_admin_audit (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  actor_id INTEGER NOT NULL,\n  action TEXT NOT NULL CHECK (action IN ('grant','revoke')),\n  created_at INTEGER NOT NULL\n);\n\nCREATE TRIGGER IF NOT EXISTS global_admin_granted AFTER INSERT ON global_admins\nWHEN NEW.active=1\nBEGIN\n  INSERT INTO global_admin_audit (user_id,actor_id,action,created_at)\n  VALUES (NEW.user_id,NEW.changed_by,'grant',NEW.changed_at);\nEND;\n\nCREATE TRIGGER IF NOT EXISTS global_admin_changed AFTER UPDATE OF active ON global_admins\nWHEN OLD.active<>NEW.active\nBEGIN\n  INSERT INTO global_admin_audit (user_id,actor_id,action,created_at)\n  VALUES (NEW.user_id,NEW.changed_by,CASE NEW.active WHEN 1 THEN 'grant' ELSE 'revoke' END,NEW.changed_at);\nEND;\n"],
  ["0011_stage_administration", "-- One representative per stable academic stage. Existing university, college, and department grants are preserved.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_single_stage_representative ON scopes(node_id)\n  WHERE type='stage' AND level='rep';\nCREATE UNIQUE INDEX IF NOT EXISTS idx_single_stage_per_representative ON scopes(user_id)\n  WHERE type='stage' AND level='rep';\n\nCREATE TABLE IF NOT EXISTS stage_announcements (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  stage_id INTEGER NOT NULL REFERENCES stages(id),\n  author_id INTEGER NOT NULL REFERENCES users(id),\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_stage_announcements_stage ON stage_announcements(stage_id,id DESC);\n"],
  ["0012_ai_dept_index", "-- فهرس نصوص ملفات القسم المشترك للمرشد الذكي. يرسله ممثل القسم أو المشرف فقط (لا يستطيع الطلبة تسميمه).\nCREATE TABLE IF NOT EXISTS ai_dept_files (\n  file_id TEXT NOT NULL,\n  department_key TEXT NOT NULL,\n  subject TEXT,\n  title TEXT,\n  pages INTEGER NOT NULL DEFAULT 0,\n  chunks INTEGER NOT NULL DEFAULT 0,\n  indexed_by TEXT,\n  indexed_at TEXT NOT NULL,\n  PRIMARY KEY (file_id, department_key)\n);\nCREATE TABLE IF NOT EXISTS ai_dept_chunks (\n  id TEXT PRIMARY KEY,\n  department_key TEXT NOT NULL,\n  file_id TEXT NOT NULL,\n  subject TEXT,\n  title TEXT,\n  page_number INTEGER NOT NULL,\n  chunk_index INTEGER NOT NULL,\n  content TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_ai_dept_chunks_dept ON ai_dept_chunks(department_key, file_id);\n"],
  ["0013_student_verification", "-- تأكيد الممثل لطلاب مرحلته. التأكيد يخصّ المرحلة المسجّل فيها الطالب فيُلغى ضمنياً إن غيّرها.\nCREATE TABLE IF NOT EXISTS student_verification (\n  user_id INTEGER PRIMARY KEY REFERENCES users(id),\n  stage_id INTEGER NOT NULL REFERENCES stages(id),\n  verified_by INTEGER NOT NULL REFERENCES users(id),\n  verified_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_student_verification_stage ON student_verification(stage_id);\n"],
  ["0014_invites_growth", "-- روابط دعوة لكل قسم أو مرحلة، وتسجيل مصدر أول تسجيل لكل طالب لتحليل النمو.\nCREATE TABLE IF NOT EXISTS invitations (\n  code TEXT PRIMARY KEY,\n  type TEXT NOT NULL CHECK (type IN ('department', 'stage')),\n  node_id INTEGER NOT NULL,\n  created_by INTEGER NOT NULL REFERENCES users(id),\n  created_at INTEGER NOT NULL,\n  revoked_at INTEGER\n);\nCREATE INDEX IF NOT EXISTS idx_invitations_node ON invitations(type, node_id);\n\nCREATE TABLE IF NOT EXISTS signup_events (\n  user_id INTEGER PRIMARY KEY REFERENCES users(id),\n  stage_id INTEGER NOT NULL REFERENCES stages(id),\n  invite_code TEXT,\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_signup_events_time ON signup_events(created_at);\n"],
  ["0015_group_chat", "-- Group chat v1: each named group belongs to exactly one academic stage.\n-- No public group roster: messages are visible only through explicit chat_members membership.\nCREATE TABLE IF NOT EXISTS chat_groups (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  stage_id INTEGER NOT NULL REFERENCES stages(id),\n  name TEXT NOT NULL,\n  invite_hash TEXT NOT NULL UNIQUE,\n  created_by INTEGER NOT NULL REFERENCES users(id),\n  created_at INTEGER NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),\n  UNIQUE(stage_id, name)\n);\nCREATE INDEX IF NOT EXISTS idx_chat_groups_stage ON chat_groups(stage_id);\n\nCREATE TABLE IF NOT EXISTS chat_members (\n  group_id INTEGER NOT NULL REFERENCES chat_groups(id),\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  joined_at INTEGER NOT NULL,\n  last_read_id INTEGER NOT NULL DEFAULT 0,\n  muted INTEGER NOT NULL DEFAULT 0 CHECK(muted IN (0,1)),\n  PRIMARY KEY(group_id, user_id)\n);\nCREATE INDEX IF NOT EXISTS idx_chat_members_user ON chat_members(user_id, group_id);\n\nCREATE TABLE IF NOT EXISTS chat_messages (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  group_id INTEGER NOT NULL REFERENCES chat_groups(id),\n  sender_id INTEGER NOT NULL REFERENCES users(id),\n  client_id TEXT NOT NULL,\n  body TEXT NOT NULL CHECK(length(body) <= 2000 AND (length(body) >= 1 OR deleted_at IS NOT NULL)),\n  reply_to INTEGER REFERENCES chat_messages(id),\n  created_at INTEGER NOT NULL,\n  edited_at INTEGER,\n  deleted_at INTEGER,\n  pinned_at INTEGER,\n  pinned_by INTEGER REFERENCES users(id),\n  UNIQUE(sender_id, client_id)\n);\nCREATE INDEX IF NOT EXISTS idx_chat_messages_group_id ON chat_messages(group_id, id);\nCREATE INDEX IF NOT EXISTS idx_chat_messages_sender ON chat_messages(sender_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_chat_messages_pinned ON chat_messages(group_id, pinned_at) WHERE pinned_at IS NOT NULL AND deleted_at IS NULL;\n\nCREATE TABLE IF NOT EXISTS chat_reports (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  message_id INTEGER NOT NULL REFERENCES chat_messages(id),\n  reporter_id INTEGER NOT NULL REFERENCES users(id),\n  reason TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  UNIQUE(message_id, reporter_id)\n);\n\nCREATE TABLE IF NOT EXISTS chat_moderation_audit (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  group_id INTEGER NOT NULL REFERENCES chat_groups(id),\n  message_id INTEGER REFERENCES chat_messages(id),\n  actor_id INTEGER NOT NULL REFERENCES users(id),\n  action TEXT NOT NULL,\n  created_at INTEGER NOT NULL\n);\n"],
  ["0016_group_chat_moderation", "CREATE TABLE IF NOT EXISTS chat_join_requests (\n  group_id INTEGER NOT NULL REFERENCES chat_groups(id),\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','revoked')),\n  requested_at INTEGER NOT NULL,\n  reviewed_by INTEGER REFERENCES users(id),\n  reviewed_at INTEGER,\n  PRIMARY KEY(group_id, user_id)\n);\nCREATE INDEX IF NOT EXISTS idx_chat_join_requests_pending ON chat_join_requests(group_id, user_id)\n  WHERE status='pending';\nCREATE INDEX IF NOT EXISTS idx_chat_join_requests_user ON chat_join_requests(user_id, requested_at DESC);\n\nCREATE TABLE IF NOT EXISTS chat_report_reviews (\n  report_id INTEGER PRIMARY KEY REFERENCES chat_reports(id),\n  decision TEXT NOT NULL CHECK(decision IN ('dismiss','remove')),\n  reviewed_by INTEGER NOT NULL REFERENCES users(id),\n  reviewed_at INTEGER NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_chat_messages_removed ON chat_messages(group_id) WHERE deleted_at IS NOT NULL;\n"],
  ["0017_hardening", "-- 0017: أدوات الإشراف على الدردشة + فهرس أداء. لا ALTER كي تبقى قابلة لإعادة التشغيل.\nCREATE TABLE IF NOT EXISTS chat_silence (\n  group_id INTEGER NOT NULL REFERENCES chat_groups(id),\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  until_at INTEGER NOT NULL,\n  set_by INTEGER NOT NULL REFERENCES users(id),\n  created_at INTEGER NOT NULL,\n  PRIMARY KEY(group_id, user_id)\n);\n-- نسخة من نص الرسالة قبل الحذف/التعديل لتبقى أدلة البلاغات\nCREATE TABLE IF NOT EXISTS chat_message_archive (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  message_id INTEGER NOT NULL,\n  body TEXT NOT NULL,\n  reason TEXT NOT NULL,\n  created_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_chat_archive_msg ON chat_message_archive(message_id);\nCREATE INDEX IF NOT EXISTS idx_chat_reports_msg ON chat_reports(message_id);\nCREATE INDEX IF NOT EXISTS idx_departments_college ON departments(college_id);\n"],
  ["0018_upload_manifest", "-- قائمة الملفات المرفوعة كانت مفتاح KV واحداً (manifest.json)؛ تنتقل إلى صفوف مستقلة في D1.\nCREATE TABLE IF NOT EXISTS upload_manifest (\n  seq INTEGER PRIMARY KEY AUTOINCREMENT,\n  id TEXT NOT NULL UNIQUE,\n  course_id TEXT,\n  json TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_upload_manifest_course ON upload_manifest(course_id);\nCREATE TABLE IF NOT EXISTS import_flags (name TEXT PRIMARY KEY, at INTEGER NOT NULL);\n"],
  ["0019_more_indexes", "-- فهارس تمنع مسح الجداول كاملة (حصة قراءة D1 اليومية)\nCREATE INDEX IF NOT EXISTS idx_stages_department ON stages(department_id);\nCREATE INDEX IF NOT EXISTS idx_terms_stage ON terms(stage_id);\nCREATE INDEX IF NOT EXISTS idx_user_profile_college ON user_profile(college_id);\nCREATE INDEX IF NOT EXISTS idx_user_profile_stage ON user_profile(stage_id);\nCREATE INDEX IF NOT EXISTS idx_scopes_type_node ON scopes(type, node_id);\n"],
  ["0020_catalog_read_indexes", "-- Index parent lookups without changing existing academic data.\nCREATE INDEX IF NOT EXISTS idx_departments_college ON departments(college_id);\nCREATE INDEX IF NOT EXISTS idx_lectures_subject ON lectures(subject_id);\nCREATE INDEX IF NOT EXISTS idx_chat_messages_unread ON chat_messages(group_id, id, sender_id)\n  WHERE deleted_at IS NULL;\n"],
  ["0021_quota_read_indexes", "-- فهارس تمنع مسح جداول كاملة في مسارات ساخنة (حصة D1 المجانية: 5 ملايين قراءة يومياً).\nCREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);\nCREATE INDEX IF NOT EXISTS idx_users_lower_email ON users(lower(email));\nCREATE INDEX IF NOT EXISTS idx_ai_quota_day ON ai_quota_ledger(day_key, status);\nCREATE INDEX IF NOT EXISTS idx_ai_chunks_user ON ai_document_chunks(user_id);\nCREATE INDEX IF NOT EXISTS idx_ai_dept_files_dept ON ai_dept_files(department_key);\nCREATE INDEX IF NOT EXISTS idx_chat_reports_reporter ON chat_reports(reporter_id, created_at);\n"]
];
